import * as React from "react";

export type TurntableIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function TurntableIcon({ size = 20, ...props }: TurntableIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="5" width="17" height="14" rx="1.5" /><circle cx="9.5" cy="12" r="4.5" /><circle cx="9.5" cy="12" r="1" />
    </svg>
  );
}
